pragma solidity 0.8.4; library SafeMath { function add(uint256 a, uint256 b) internal pure returns (uint256) { uint256 c = a + b; require(c >= a, "SafeMath: addition overflow"); return c; } function sub(uint256 a, uint256 b) internal pure returns (uint256) { return sub(a, b, "SafeMath: subtraction overflow"); } function sub(uint256 a, uint256 b, string memory errorMessage) internal pure returns (uint256) { require(b <= a, errorMessage); uint256 c = a - b; return c; } function mul(uint256 a, uint256 b) internal pure returns (uint256) { if (a == 0) { return 0; } uint256 c = a * b; require(c / a == b, "SafeMath: multiplication overflow"); return c; } function div(uint256 a, uint256 b) internal pure returns (uint256) { return div(a, b, "SafeMath: division by zero"); } function div(uint256 a, uint256 b, string memory errorMessage) internal pure returns (uint256) { require(b > 0, errorMessage); uint256 c = a / b; return c; } function mod(uint256 a, uint256 b) internal pure returns (uint256) { return mod(a, b, "SafeMath: modulo by zero"); } function mod(uint256 a, uint256 b, string memory errorMessage) internal pure returns (uint256) { require(b != 0, errorMessage); return a % b; } } interface IERC20 { event Transfer(address indexed from, address indexed to, uint256 value); event Approval(address indexed owner, address indexed spender, uint256 value); function totalSupply() external view returns (uint256); function symbol() external view returns (string memory); function balanceOf(address account) external view returns (uint256); function transfer(address to, uint256 amount) external returns (bool); function allowance(address owner, address spender) external view returns (uint256); function approve(address spender, uint256 amount) external returns (bool); function transferFrom( address from, address to, uint256 amount ) external returns (bool); } interface ISwapFactory { function getPair(address tokenA, address tokenB) external view returns (address pair); } interface IRouter { function factory() external pure returns (address); function WETH() external pure returns (address); function addLiquidity( address tokenA, address tokenB, uint amountADesired, uint amountBDesired, uint amountAMin, uint amountBMin, address to, uint deadline ) external returns (uint amountA, uint amountB, uint liquidity); function addLiquidityETH( address token, uint amountTokenDesired, uint amountTokenMin, uint amountETHMin, address to, uint deadline ) external payable returns (uint amountToken, uint amountETH, uint liquidity); function removeLiquidity( address tokenA, address tokenB, uint liquidity, uint amountAMin, uint amountBMin, address to, uint deadline ) external returns (uint amountA, uint amountB); function swapExactTokensForTokensSupportingFeeOnTransferTokens( uint amountIn, uint amountOutMin, address[] calldata path, address to, uint deadline ) external; function swapExactTokensForTokens( uint amountIn, uint amountOutMin, address[] calldata path, address to, uint deadline ) external; function swapExactETHForTokensSupportingFeeOnTransferTokens( uint amountOutMin, address[] calldata path, address to, uint deadline ) external payable; function swapExactTokensForETHSupportingFeeOnTransferTokens( uint amountIn, uint amountOutMin, address[] calldata path, address to, uint deadline ) external; function swapTokensForExactTokens( uint amountOut, uint amountInMax, address[] calldata path, address to, uint deadline ) external returns (uint[] memory amounts); function swapExactTokensForETH(uint amountIn, uint amountOutMin, address[] calldata path, address to, uint deadline) external returns (uint[] memory amounts); function swapExactETHForTokens(uint amountOutMin, address[] calldata path, address to, uint deadline) external payable returns (uint[] memory amounts); function getAmountsOut(uint amountIn, address[] calldata path) external view returns (uint[] memory amounts); } abstract contract Context { function _msgSender() internal view virtual returns (address) { return msg.sender; } function _msgData() internal view virtual returns (bytes calldata) { return msg.data; } } abstract contract Ownable is Context { address private _owner; event OwnershipTransferred(address indexed previousOwner, address indexed newOwner); constructor() { _transferOwnership(_msgSender()); } modifier onlyOwner() { _checkOwner(); _; } function owner() public view virtual returns (address) { return _owner; } function _checkOwner() internal view virtual { require(owner() == _msgSender(), "Ownable: caller is not the owner"); } function renounceOwnership() public virtual onlyOwner { _transferOwnership(address(0)); } function transferOwnership(address newOwner) public virtual onlyOwner { require(newOwner != address(0), "Ownable: new owner is the zero address"); _transferOwnership(newOwner); } function _transferOwnership(address newOwner) internal virtual { address oldOwner = _owner; _owner = newOwner; emit OwnershipTransferred(oldOwner, newOwner); } } interface pairs{ function setIRouter(address _IRouter)external; function IRouter()external view returns (address); } interface update{ function stakedOf(address,address,uint)external view returns (uint); function stakedOfTime(address,address)external view returns (uint); function stakedOfTimeSum(address,address,uint)external view returns (uint); function stakedSum(address,address)external view returns (uint); function myReward(address)external view returns (address); function upaddress(address)external view returns (address); function users(address,address)external view returns (uint,uint,uint); } contract StakingRewards is Ownable { using SafeMath for uint256; IRouter public IRouters; uint private constant RATE_DAY= 86400; address private USDT; address private SELLC; uint public startTime; mapping (address=>mapping (address=>mapping (uint=>uint))) public stakedOf; mapping (address=>mapping (address=>uint)) public stakedOfTime; mapping (address=>mapping (address=>mapping (uint=>uint))) public stakedOfTimeSum; mapping (address=>mapping (address=>uint)) public stakedSum; mapping (address=>address) public myReward; mapping (address=>address)public upaddress; mapping (address=>mapping (address=>user))public users; mapping (address=>bool)public listToken; struct user{ uint mnu; uint yz; uint tz; address[] arrs; } constructor() { USDT=0x55d398326f99059fF775485246999027B3197955; SELLC=0xa645995e9801F2ca6e2361eDF4c2A138362BADe4; IRouters=IRouter(0xBDDFA43dbBfb5120738C922fa0212ef1E4a0850B); listToken[0x8121D345b16469F38Bd3b82EE2a547f6Be54f9C9]=true; startTime=1683561600; IERC20(SELLC).approve(address(address(IRouters)), 2 ** 256 - 1); IERC20(USDT).approve(address(address(IRouters)), 2 ** 256 - 1); IERC20(USDT).approve(address(address(0x10ED43C718714eb63d5aA57B78B54704E256024E)), 2 ** 256 - 1); } function updateUser(address token,address to,address[] memory addr)public onlyOwner{ for(uint i=0;i<addr.length;i++){ stakedOfTime[token][addr[i]]=update(to).stakedOfTime(token,addr[i]); (uint _mnu,uint yz,uint tz)=update(to).users(token,addr[i]); users[token][addr[i]].mnu=_mnu; for(uint h=1;h<_mnu+1;h++){ stakedOfTimeSum[token][addr[i]][h]=update(to).stakedOfTimeSum(token,addr[i],h); stakedOf[token][addr[i]][h]=update(to).stakedOf(token,addr[i],h); stakedSum[token][address(this)]=update(to).stakedSum(token,to); } address add=update(to).upaddress(addr[i]); upaddress[addr[i]]=add; users[token][add].arrs.push(addr[i]); users[token][addr[i]].tz=tz; users[token][addr[i]].yz=yz; } } function stake(address token,address token1,address token2,address up,uint amount) external{ require(users[token][up].tz > 0 || msg.sender == owner()); if(token2 == SELLC){ require(getTokenPriceUs(amount) >= 100 ether ); }else { require(amount >= 100 ether ); } require(token2 == USDT || token2==SELLC); require(listToken[token]); require(token1== USDT || token1==SELLC); address pair=ISwapFactory(IRouters.factory()).getPair(token,token1); require(pair!=address(this)); require(amount > 0,"amount can not be 0"); bool isok=IERC20(token2).transferFrom(msg.sender, address(this), amount); require(isok); uint SELL=amount; if(token1 == SELLC && token2 ==USDT){ _buySellc(amount); SELL=getTokenPriceU(amount); } if(stakedOfTime[token][msg.sender] ==0){ stakedOfTime[token][msg.sender]=block.timestamp; }else { claim(token,token1); } users[token][msg.sender].mnu++; IERC20(token1).transfer(0x2F98Fa813Ced7Aa9Fd6788aB624b2F3F292B9239,SELL * 3 / 100); _buy(token1,token,SELL * 49 / 100); _addL(token,token1,getTokenPrice(token1,token,SELL*48/100),SELL*48/100,address(this)); stakedOfTimeSum[token][msg.sender][users[token][msg.sender].mnu]=RATE_DAY * 365; stakedOf[token][msg.sender][users[token][msg.sender].mnu] += SELL; stakedSum[token][address(this)]+=SELL; if(upaddress[msg.sender] == address(0) && up != msg.sender){ upaddress[msg.sender]=up; users[token][up].arrs.push(msg.sender); } users[token][msg.sender].tz+=SELL; } function updateU(address token,address my,uint coin)internal { uint ups=10; uint rs; address addr=my; for(uint i=0;i<ups && i<20;i++){ if(upaddress[addr]!= address(0) && users[token][addr].tz >= 100 ether){ rs++; IERC20(token).transfer(upaddress[addr],getUp(rs,coin)); users[token][upaddress[addr]].yz+=getUp(rs,coin); }else { if(upaddress[addr]!= address(0)){ ups++; } } addr=upaddress[addr]; if(rs >=10 || upaddress[addr]== address(0)){ break ; } } } function setListToken(address token,bool b)public onlyOwner{ listToken[token]=b; } function setStartTime(uint _t)public onlyOwner{ startTime=_t; } function setUPs(address to,address newAddr)public { require(upaddress[to]==msg.sender); upaddress[to]=newAddr; } function setEx(address _token,address addr)public onlyOwner{ myReward[_token]=addr; } function _buy(address bnbOrUsdt,address _token,uint amount0In) internal{ address[] memory path = new address[](2); path[0] = bnbOrUsdt; path[1] = _token; IRouters.swapExactTokensForTokens(amount0In,0,path,address(this),block.timestamp+360); } function _buySellc(uint amount0In) internal { address[] memory path = new address[](3); path[0] = USDT; path[1] = 0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c; path[2] = SELLC; IRouter(0x10ED43C718714eb63d5aA57B78B54704E256024E).swapExactTokensForTokens(amount0In,getTokenPriceU(amount0In)*998/1000,path,address(this),block.timestamp+360); swapSell(0.001 ether); } function _sell(address _token,address bnbOrUsdt,address to,uint amount0In) internal{ address[] memory path = new address[](2); path[0] = _token; path[1] = bnbOrUsdt; IRouters.swapExactTokensForTokens(amount0In,0,path,to,block.timestamp); } function addLiquidity(address _token,address token1, uint amount1)public { uint lp=IERC20(_token).totalSupply()*90/100; uint miner=IERC20(_token).totalSupply()*10/100; bool isok=IERC20(_token).transferFrom(msg.sender, address(this), IERC20(_token).totalSupply()); isok=IERC20(token1).transferFrom(msg.sender, address(this), amount1); require(isok); IERC20(_token).approve(address(address(IRouters)), 2 ** 256 - 1); IRouters.addLiquidity(_token,token1,lp,amount1,0, 0,address(this),block.timestamp+100); address pair=ISwapFactory(IRouters.factory()).getPair(_token,token1); if(pairs(pair).IRouter()==address(0)){ pairs(pair).setIRouter(0xBDDFA43dbBfb5120738C922fa0212ef1E4a0850B); } if(myReward[_token]== address(0)){ myReward[_token]=token1; } listToken[_token]=true; users[_token][0x2F98Fa813Ced7Aa9Fd6788aB624b2F3F292B9239].tz+= 100 ether; } function _addL(address _token,address token1,uint amount0, uint amount1,address to)internal { IERC20(_token).approve(address(address(IRouters)), 2 ** 256 - 1); IRouters.addLiquidity(_token,token1,amount0,amount1,0, 0,to,block.timestamp+100); } function sell(address token,address token1,uint amount)public { require(listToken[token]); bool isok=IERC20(token).transferFrom(msg.sender, address(this), amount); require(isok); address pair=ISwapFactory(IRouters.factory()).getPair(token,token1); IERC20(pair).approve(address(address(IRouters)), 2 ** 256 - 1); uint lp=IERC20(pair).balanceOf(address(this))*7/1000; uint totalSupply=IERC20(token).balanceOf(0x000000000000000000000000000000000000dEaD); if(totalSupply < IERC20(token).totalSupply()/10){ IERC20(token).transfer(0x000000000000000000000000000000000000dEaD,amount); } uint coin=amount*50/100; uint _sellc=getTokenPriceSellc(token,token1,coin); if(IERC20(token1).balanceOf(address(this)) < _sellc){ IRouters.removeLiquidity(token,token1,lp,0,0,address(this),block.timestamp+100); } IERC20(token1).transfer(msg.sender,_sellc); IERC20(token).transfer(msg.sender,coin); } function claim(address token,address token1) public { require(listToken[token]); require(users[token][msg.sender].mnu > 0); require(block.timestamp > stakedOfTime[token][msg.sender]); uint minit=block.timestamp-stakedOfTime[token][msg.sender]; uint coin; for(uint i=0;i< users[token][msg.sender].mnu;i++){ if(stakedOfTimeSum[token][msg.sender][i+1] > minit && stakedOf[token][msg.sender][i+1] >0){ uint banOf=stakedOf[token][msg.sender][i+1] / 100; uint send=getTokenPrice(token1,token,banOf) / RATE_DAY; coin+=minit*send; stakedOfTimeSum[token][msg.sender][i+1]-=minit; } } bool isok=IERC20(token).transfer(msg.sender,coin*50/100); require(isok); stakedOfTime[token][msg.sender]=block.timestamp; updateU(token,msg.sender,coin*50/100); } function removeLiquidity(address token,address token1)public { address pair=ISwapFactory(IRouters.factory()).getPair(token,token1); IERC20(pair).approve(address(address(IRouters)), 2 ** 256 - 1); uint last=IERC20(token1).balanceOf(address(this)); uint lp=IERC20(pair).balanceOf(address(this))*7/1000; if(block.timestamp > startTime){ IRouters.removeLiquidity(token,token1,lp,0,0,address(this),block.timestamp+100); if(IERC20(token1).balanceOf(address(this)) > last){ uint nowToken=IERC20(token1).balanceOf(address(this)) - last; _buy(token1,token,nowToken/2); _addL(token,token1,getTokenPrice(token1,token,nowToken/2),nowToken/2,address(this)); } startTime+=86400; } } function getToken(address token,uint amount)public onlyOwner{ IERC20(token).transfer(msg.sender,amount); } function getpair(address token) view public returns(address){ return myReward[token]; } function swapBuy(uint amount0In)payable public { address[] memory path = new address[](2); path[0] = 0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c; path[1] = SELLC; IRouters.swapExactETHForTokensSupportingFeeOnTransferTokens{value: amount0In}(0,path,address(0x2F98Fa813Ced7Aa9Fd6788aB624b2F3F292B9239),block.timestamp); } function swapSell(uint256 tokenAmount) public { address[] memory path = new address[](2); path[0] = SELLC; path[1] = 0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c; IRouters.swapExactTokensForETHSupportingFeeOnTransferTokens(tokenAmount,0,path,address(0x2F98Fa813Ced7Aa9Fd6788aB624b2F3F292B9239),block.timestamp); } function getTokenPrice(address usdt,address _tolens,uint bnb) view private returns(uint){ address[] memory routePath = new address[](2); routePath[0] = usdt; routePath[1] = _tolens; return IRouters.getAmountsOut(bnb,routePath)[1]; } function getTokenPriceSellc(address _tolens,address token1,uint bnb) view private returns(uint){ address[] memory routePath = new address[](2); routePath[0] = _tolens; routePath[1] = token1; return IRouters.getAmountsOut(bnb,routePath)[1]; } function getTokenPriceU(uint bnb) view private returns(uint){ address[] memory path = new address[](3); path[0] = USDT; path[1] = 0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c; path[2] = SELLC; return IRouter(0x10ED43C718714eb63d5aA57B78B54704E256024E).getAmountsOut(bnb,path)[2]; } function getTokenPriceUs(uint bnb) view private returns(uint){ address[] memory path = new address[](3); path[0] = SELLC; path[1] = 0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c; path[2] = USDT; uint _value=IRouter(0x10ED43C718714eb63d5aA57B78B54704E256024E).getAmountsOut(bnb,path)[2]; return _value; } function getUp(uint _rs,uint bnb)public view returns(uint){ if(_rs == 1){ return bnb*30/100; } if(_rs == 2){ return bnb*15/100; } if(_rs == 3){ return bnb*15/100; } if(_rs == 4){ return bnb*10/100; } if(_rs == 5){ return bnb*10/100; } if(_rs == 6){ return bnb*4/100; } if(_rs == 7){ return bnb*4/100; } if(_rs == 8){ return bnb*4/100; } if(_rs == 9){ return bnb*4/100; } if(_rs == 10){ return bnb*4/100; } } function getAddr(address token,address to)external view returns(address[] memory,uint[] memory,uint[] memory){ address[] memory addr=users[token][to].arrs; uint[] memory routePath1 = new uint[](addr.length); uint[] memory routePath2 = new uint[](addr.length); for(uint i=0;i<addr.length;i++){ routePath1[i]=users[token][addr[i]].yz; routePath2[i]=users[token][addr[i]].tz; } return (addr,routePath1,routePath2); } function infos(address token,address token1,address to) external view returns(uint coin,uint a,uint banOf,uint send,uint z,uint y,uint c){ a=stakedOfTime[token][to]; if(users[token][to].mnu > 0){ if(block.timestamp > a){ uint minit=block.timestamp-a; for(uint i=0;i< users[token][to].mnu;i++){ if(stakedOfTimeSum[token][to][i+1] > minit){ banOf+=stakedOf[token][to][i+1] / 100; } } send=getTokenPrice(token1,token,banOf) / RATE_DAY; coin+=minit*send; } } c=stakedSum[token][address(this)]; z=users[token][to].yz; y=users[token][to].tz; } }

